import{r as e}from"./chunks/relatedArticles.DIHQAH-1.js";import{I as o,o as i,c as r,b6 as l,J as n,k as d}from"./chunks/framework.BUXTSoD9.js";const b=JSON.parse('{"title":"من الفكرة إلى منتج AI - خريطة طريق تعلم Easy-Vibe","description":"خريطة طريق كاملة لتعلم برمجة الذكاء الاصطناعي: من الصفر إلى التطوير الشامل. أتقن أدوات AI IDE مثل Vibe Coding و Claude Code و Cursor، وتعلم التفكير في المنتجات والتطوير الشامل وتكامل قدرات الذكاء الاصطناعي.","frontmatter":{"title":"من الفكرة إلى منتج AI - خريطة طريق تعلم Easy-Vibe","description":"خريطة طريق كاملة لتعلم برمجة الذكاء الاصطناعي: من الصفر إلى التطوير الشامل. أتقن أدوات AI IDE مثل Vibe Coding و Claude Code و Cursor، وتعلم التفكير في المنتجات والتطوير الشامل وتكامل قدرات الذكاء الاصطناعي."},"headers":[],"relativePath":"ar-sa/stage-1/learning-map/index.md","filePath":"ar-sa/stage-1/learning-map/index.md"}'),p={name:"ar-sa/stage-1/learning-map/index.md"},q=Object.assign(p,{setup(c){const a=e["ar-sa/stage-1/learning-map"]??[];return(u,t)=>{const s=o("RelatedArticlesSection");return i(),r("div",null,[t[0]||(t[0]=l('<h1 id="من-الفكرة-إلى-منتج-ai" tabindex="-1">من الفكرة إلى منتج AI <a class="header-anchor" href="#من-الفكرة-إلى-منتج-ai" aria-label="Permalink to “من الفكرة إلى منتج AI”">​</a></h1><div class="info custom-block"><p class="custom-block-title">شكر خاص</p><p>شكر خاص لطلاب <strong>جامعة تسينغهوا بم-campus شنتشن الدولي للدراسات العليا</strong> على اختبار هذه الدورة التدريبية وتقديم الملاحظات والدعم! آراؤكم ومساهماتكم جعلت هذه الدورة أفضل. <a href="https://github.com/datawhalechina/easy-vibe#-contributing--contributors" target="_blank" rel="noreferrer">👉 عرض قائمة المساهمين الكاملة</a></p></div><p>في الماضي، كان صنع البرمجيات يتطلب مستوى عالٍ: كنت بحاجة إلى فهم البرمجة والخوارزميات، والحصول على خبرة مشروع لعدة سنوات. الآن الأمر مختلف. طالما لديك فكرة، يمكن للذكاء الاصطناعي مساعدتك في كتابة التعليمات البرمجية.</p><p>هذا تغيير كبير: <strong>لغات البرمجة أصبحت لغات طبيعية</strong>.</p><p>مع ظهور النماذج اللغوية الكبيرة (LLM)، لم يعد التطوير &quot;حكرًا على خبراء التقنية&quot;، بل أصبح أداة يمكن للجميع استخدامها. كان أصعب جزء في الماضي هو &quot;كيفية كتابة التعليمات البرمجية&quot;، أما الآن فأصعب جزء هو &quot;<strong>ماذا تريد أن تصنع</strong>&quot;.</p><blockquote><p><strong>ما هو Vibe Coding؟</strong> ببساطة، هو &quot;البرمجة بالكلام&quot;. Vibe Coding يعني أنه يمكنك الاعتماد على التحدث مع الذكاء الاصطناعي فقط، بدلاً من كتابة التعليمات البرمجية مباشرة، لإكمال مشاريع البرمجة.</p></blockquote><p>بالطبع، جعل الذكاء الاصطناعي يكتب التعليمات البرمجية هو مجرد الخطوة الأولى. لصنع منتج حقيقي قابل للاستخدام، ستواجه هذه المشكلات:</p><ul><li>كيف تجعل الذكاء الاصطناعي يكتب تعليمات برمجية نظيفة وقابلة للصيانة؟</li><li>كيف تجمع التعليمات البرمجية المتناثرة في تطبيق يعمل؟</li><li>كيف تجعل التطبيق يعمل فعليًا ويستخدمه الناس؟</li><li>كيف تدمج قدرات الذكاء الاصطناعي مثل إنشاء النصوص والتعرف على الصور في منتجك؟</li></ul><p>ستجد الإجابات على هذه الأسئلة في هذه الدورة.</p><p>سواء كنت طالبًا أو معلمًا أو طبيبًا أو عاملًا أو أي شخص عادي لا يعرف أي شيء عن التقنية - لا تحتاج إلى تعلم البرمجة لسنوات، يمكنك صنع نموذج أولي للمنتج يعمل ويمكن عرضه في غضون أسبوعين.</p><table tabindex="0"><thead><tr><th>هويتك</th><th>ما يمكن أن تساعدك هذه الدورة</th></tr></thead><tbody><tr><td>طالب</td><td>الواجبات والمسابقات وريادة الأعمال، اصنع مشاريعك بنفسك، بدلاً من طلب المساعدة من الآخرين</td></tr><tr><td>محترف</td><td>أتمتة العمل المتكرر، تحسين الكفاءة، حتى تطوير مشروع جانبي</td></tr><tr><td>مدير منتجات / مصمم</td><td>الأفكار لم تعد تبقى على الورق، يمكنك إنشاء عرض تجريبي سريع لرؤسائك/عملائك</td></tr><tr><td>رائد أعمال / صاحب مشروع صغير</td><td>التحقق من الأفكار بتكلفة منخفضة، يمكنك صنع MVP دون إنفاق آلاف على الاستعانة بمصادر خارجية</td></tr><tr><td>معلم / عامل في مجال التعليم</td><td>إنشاء أدوات تعليمية ومواد دورات والاختبار الآلي، تحسين كفاءة التدريس</td></tr><tr><td>طبيب / محامي / عامل محترف</td><td>أتمتة العمليات المهنية، وبناء أدوات الكفاءة الخاصة بك</td></tr><tr><td>أي شخص</td><td>استخدام الذكاء الاصطناعي لحل مشكلات محددة في الحياة/العمل، تحويل المستحيل إلى ممكن</td></tr></tbody></table><p>في عصر الذكاء الاصطناعي، القدرة على التنفيذ والأفكار أهم دائمًا من التقنية.</p><h2 id="مسار-النمو-من-يعرف-استخدام-الذكاء-الاصطناعي-إلى-يعرف-صنع-منتجات-الذكاء-الاصطناعي" tabindex="-1">مسار النمو: من &quot;يعرف استخدام الذكاء الاصطناعي&quot; إلى &quot;يعرف صنع منتجات الذكاء الاصطناعي&quot; <a class="header-anchor" href="#مسار-النمو-من-يعرف-استخدام-الذكاء-الاصطناعي-إلى-يعرف-صنع-منتجات-الذكاء-الاصطناعي" aria-label="Permalink to “مسار النمو: من &quot;يعرف استخدام الذكاء الاصطناعي&quot; إلى &quot;يعرف صنع منتجات الذكاء الاصطناعي&quot;”">​</a></h2><div class="stage-intro"><div class="stage-card"><div class="stage-icon">🎮</div><h3>دليل المبتدئين</h3><p class="stage-role">تجربة برمجة الذكاء الاصطناعي</p><div class="stage-tags"><span>لعبة الثعبان الصغيرة</span><span>البدء من الصفر</span><span>أول تجربة لـ Vibecoding</span><span>إنشاء في بضع دقائق</span></div></div></div><div class="stage-grid"><div class="stage-card"><div class="stage-icon">🛠️</div><h3>المرحلة الأولى</h3><p class="stage-role">مدير المنتجات / العمليات</p><div class="stage-tags"><span>AI IDE (Cursor/Claude)</span><span>تفكيك المتطلبات والنماذج الأولية</span><span>تكامل قدرات الذكاء الاصطناعي</span><span>تطوير Demo كامل</span></div></div><div class="stage-card"><div class="stage-icon">💻</div><h3>المرحلة الثانية</h3><p class="stage-role">مطور متوسط/مبتدئ / مطور مستقل</p><div class="stage-tags"><span>من Figma إلى التعليمات البرمجية</span><span>قاعدة بيانات Supabase</span><span>تكامل دفع Stripe</span><span>قاعدة معرفة Dify</span></div></div><div class="stage-card"><div class="stage-icon">🚀</div><h3>المرحلة الثالثة</h3><p class="stage-role">مطور متقدم / مهندس معماري</p><div class="stage-tags"><span>ويب/تطبيقات صغيرة/متعدد المنصات</span><span>أدوات MCP المتقدمة</span><span>RAG &amp; LangGraph</span><span>تفكير المهندس المتقدم</span></div></div></div><p>من خلال مسار التعلم الكامل هذا، ستحصل على:</p><ul><li><strong>قدرة تطوير Vibe Coding:</strong> إتقان التفكير في vibecoding وأدوات الترميز بالذكاء الاصطناعي، وزيادة كفاءة التطوير عدة مرات. لم تعد بحاجة إلى حفظ القواعد عن ظهر قلب، بل تعلم كيفية توجيه الذكاء الاصطناعي لتوليد تعليمات برمجية عالية الجودة.</li><li><strong>مهارات التطوير الشامل:</strong> من تصميم واجهة المستخدم إلى تنفيذ الواجهة الأمامية، من تصميم قاعدة البيانات إلى تطوير API، من التطوير المحلي إلى النشر السحابي، إتقان مجموعة التقنيات الكاملة لتطبيقات الويب الحديثة.</li><li><strong>تكامل قدرات الذكاء الاصطناعي:</strong> تعلم استدعاء واجهات برمجة تطبيقات الذكاء الاصطناعي متعددة الوسائط المختلفة، ودمج قدرات الذكاء الاصطناعي مثل النصوص والصور والكلام بسلاسة في تطبيقاتك، وبناء منتجات ذكية من خلال تقنيات مثل RAG.</li><li><strong>التفكير في المنتجات وقدرات العمليات:</strong> من بحث المستخدمين إلى تفكيك المتطلبات، من تصميم MVP إلى تكرار المنتج، من تكامل المدفوعات إلى إدارة المستخدمين، تشكيل حلقة كاملة من تطوير المنتجات والعمليات.</li></ul><h1 id="ماذا-يمكنك-أن-تفعل-بعد-التعلم؟" tabindex="-1">ماذا يمكنك أن تفعل بعد التعلم؟ <a class="header-anchor" href="#ماذا-يمكنك-أن-تفعل-بعد-التعلم؟" aria-label="Permalink to “ماذا يمكنك أن تفعل بعد التعلم؟”">​</a></h1><h2 id="المرحلة-الأولى-اصنع-نموذجك-الأولي-للمنتج" tabindex="-1">المرحلة الأولى: اصنع نموذجك الأولي للمنتج <a class="header-anchor" href="#المرحلة-الأولى-اصنع-نموذجك-الأولي-للمنتج" aria-label="Permalink to “المرحلة الأولى: اصنع نموذجك الأولي للمنتج”">​</a></h2><p>هذه المرحلة مناسبة للطلاب الذين ليس لديهم أساس برمجي على الإطلاق، أو الذين يعرفون القليل فقط لكنهم ليسوا واثقين. لا تحتاج إلى تعلم الكثير من النظريات أولاً، بل اتبع الخطوات مباشرة وتعلم استخدام أدوات الذكاء الاصطناعي لكتابة التعليمات البرمجية أثناء العملية.</p><p><strong>بعد التعلم ستتمكن من</strong>:</p><ul><li>استخدام أدوات برمجة الذكاء الاصطناعي بشكل مستقل لإكمال تطبيق ويب</li><li>تحويل أفكار المنتجات إلى نماذج أولية قابلة للنقر والتفاعل</li><li>إضافة ميزات ذكاء اصطناعي للنموذج الأولي (مثل إنشاء الصور من النصوص، المحادثة الذكية)</li><li>معرفة كيفية استكشاف الأخطاء وإصلاحها عند مواجهتها</li></ul><p>ببساطة، ستتمكن من صنع شيء &quot;يعمل ويمكن عرضه للآخرين&quot;.</p><p>يمكننا أولاً تجربة برمجة الذكاء الاصطناعي من خلال الألعاب الصغيرة، ثم تعلم كيفية استخدام أدوات برمجة الذكاء الاصطناعي لمساعدتك في كتابة التعليمات البرمجية وإصلاح الأخطاء. ثم البدء بصفحة بسيطة، والعمل تدريجيًا نحو تطبيق متعدد الصفحات تفاعلي، ثم إضافة ميزات ذكاء اصطناعي مثل إنشاء الصور من النصوص والمحادثة الذكية. أخيرًا، إكمال مشروع كامل بشكل مستقل، مما يتيح لأفكارك الإبداعية فرصة حقيقية للتحقق.</p><h1 id="لماذا-نستخدم-نهج-قائم-على-المشاريع-للتدريب؟" tabindex="-1">لماذا نستخدم نهج قائم على المشاريع للتدريب؟ <a class="header-anchor" href="#لماذا-نستخدم-نهج-قائم-على-المشاريع-للتدريب؟" aria-label="Permalink to “لماذا نستخدم نهج قائم على المشاريع للتدريب؟”">​</a></h1><blockquote><p><strong>تحديات العالم الحقيقي</strong></p><p>السبب في الواقع بسيط جدًا: بالنظر إلى حالة معظم الطلاب حاليًا، عند الدخول المباشر إلى سوق العمل، من المرجح جدًا أن تواجه صعوبات في المشاريع الحقيقية وتحت &quot;الضرب المجتمعي&quot; من الرؤساء/العملاء. المشاهد الأكثر شيوعًا في العالم الحقيقي هي:</p></blockquote><blockquote><p>مديرك/رئيسك: نريد صنع xxx، والهدف هو تحقيق تأثير yyy.</p><p>الوثائق؟ الأطر الجاهزة؟ مواصفات المتطلبات التفصيلية؟ في كثير من الأحيان لا يوجد أي منها.</p></blockquote><p>العديد من المهام في العمل الحقيقي هي في جوهرها حل مشكلات لم يسبق رؤيتها من قبل في بيئة عالية عدم اليقين: المتطلبات غامضة، والحدود متغيرة، ولا أحد يخبرك بالإجابة الصحيحة، تحتاج إلى البحث عن المعلومات بنفسك، وإجراء التجارب، وبناء النماذج الأولية، والتكرار المستمر، وأخيرًا تقديم حل &quot;يعمل ويمكن استخدامه ويمكن إطلاقه&quot;.</p><p>ما تريد هذه الدورة القيام به هو إعطائك &quot;محاكاة للضرب المجتمعي&quot; مسبقًا في بيئة آمنة نسبيًا:</p><ul><li>من خلال مهام مشروع تبدو صعبة إلى حد ما، إجبارك على ممارسة تفكيك المشكلات، وتصميم الحلول، والبحث عن المعلومات بنفسك</li><li>من خلال السقالات والتعليمات البرمجية غير &quot;المبسطة&quot;، ستتعلم قراءة وفهم وتعديل قاعدة تعليمات برمجية متوسطة إلى كبيرة</li><li>من خلال الحلقة الكاملة من الفكرة إلى الإطلاق، ستجرب العملية الكاملة للمنتج من الصفر إلى الواحد</li></ul><p>على المدى القصير، هذا التدريب مؤلم بالفعل؛ لكن على المدى الطويل، سيعزز بشكل كبير قدرتك التنافسية في البحث عن عمل والتطور المهني: ستكون أكثر قدرة على تحمل المسؤوليات، وأكثر قدرة على إيجاد اختراقات في بيئات غير مؤكدة، وأكثر قدرة على تحويل الذكاء الاصطناعي إلى منتجات حقيقية، بدلاً من البقاء عند مرحلة &quot;تجربة العرض التوضيحي&quot;.</p><h1 id="فن-طرح-الأسئلة-مهارة-أساسية-في-عصر-الذكاء-الاصطناعي" tabindex="-1">فن طرح الأسئلة: مهارة أساسية في عصر الذكاء الاصطناعي <a class="header-anchor" href="#فن-طرح-الأسئلة-مهارة-أساسية-في-عصر-الذكاء-الاصطناعي" aria-label="Permalink to “فن طرح الأسئلة: مهارة أساسية في عصر الذكاء الاصطناعي”">​</a></h1><p>في عصر الذكاء الاصطناعي، طرح الأسئلة هو أيضًا نوع من &quot;المهارات الأساسية&quot;. نفس التعليمات البرمجية، نفس الخطأ، <strong>كيف تطرح سؤالك يحدد تقريبًا نوع الإجابة التي يمكن للذكاء الاصطناعي تقديمها</strong>: هل هي إجابة عامة، أم حلول قابلة للتنفيذ خطوة بخطوة.</p><p><strong>عادات جيدة</strong>: اجعل &quot;سؤال الذكاء الاصطناعي&quot; جزءًا من عملية التطوير اليومية: عندما تواجه شيئًا لا تفهمه أو مشكلة عالقة، اسأل على الفور.</p><h2 id="لماذا-هذه-مهارة-أساسية؟" tabindex="-1">لماذا هذه مهارة أساسية؟ <a class="header-anchor" href="#لماذا-هذه-مهارة-أساسية؟" aria-label="Permalink to “لماذا هذه مهارة أساسية؟”">​</a></h2><ul><li><strong>نادرًا ما توجد وثائق كاملة في الواقع</strong>: في أغلب الأحيان تواجه متطلبات غير واضحة، تعليمات برمجية نصف مكتملة، رسائل خطأ متفرقة</li><li><strong>الذكاء الاصطناعي هو معلمك وزميلك في أي وقت</strong>: الشخص الذي يعرف كيف يسأل يمكن أن يحول الذكاء الاصطناعي إلى &quot;برمجة زوجية عالية الجودة&quot;</li><li><strong>الحد الأعلى للقدرة يحدده التواصل</strong>: كلما زادت المعلومات الرئيسية التي تقدمها، وكلما كان تنسيق المخرجات أكثر تحكمًا، كانت الإجابة أكثر قابلية للاستخدام</li></ul><p><strong>سوء فهم شائع</strong>: سؤال واحد فقط &quot;لماذا الخطأ؟&quot; عادة ما يحصل فقط على كومة من التخمينات. املأ السياق، وستحصل على حلول قابلة للتنفيذ.</p><h2 id="كيفية-إطعام-المعلومات-للذكاء-الاصطناعي-لقطات-الشاشة-مقابل-النسخ-واللصق" tabindex="-1">كيفية &quot;إطعام&quot; المعلومات للذكاء الاصطناعي: لقطات الشاشة مقابل النسخ واللصق <a class="header-anchor" href="#كيفية-إطعام-المعلومات-للذكاء-الاصطناعي-لقطات-الشاشة-مقابل-النسخ-واللصق" aria-label="Permalink to “كيفية &quot;إطعام&quot; المعلومات للذكاء الاصطناعي: لقطات الشاشة مقابل النسخ واللصق”">​</a></h2><p>كلتا الطريقتين ممكنتان، لكن للاستخدامات المختلفة:</p><table tabindex="0"><thead><tr><th>الطريقة</th><th>سيناريو الاستخدام</th><th>المتطلبات الرئيسية</th></tr></thead><tbody><tr><td><strong>النسخ واللصق</strong></td><td>تتبع أخطاء المكدس، السجلات، التعليمات البرمجية، التكوينات، إرجاع API</td><td>حاول أن تكون كاملاً، لا تقتطع سطرًا واحدًا من الكلمات الرئيسية</td></tr><tr><td><strong>لقطة شاشة</strong></td><td>مشاكل تخطيط UI، التفاعلات غير الطبيعية، أزرار واجهة الأدوات غير موجودة</td><td>لقطة شاشة كاملة + حدد المنطقة الرئيسية، من الأفضل إضافة جملة وصفية نصية</td></tr></tbody></table><div class="danger custom-block"><p class="custom-block-title">⚠️ شرط مسبق مهم</p><p><strong>ليس كل الذكاء الاصطناعي يدعم إدخال الصور.</strong> التواصل بلقطات الشاشة يتطلب أن يمتلك الذكاء الاصطناعي قدرات متعددة الوسائط (أي القدرة على فهم وتحليل الصور). حاليًا، تشمل نماذج الذكاء الاصطناعي التي تدعم إدخال الصور: Claude (Anthropic)، GPT-4V/GPT-4o (OpenAI)، Gemini (Google)، وبعض النماذج المحلية الكبيرة.</p><p><strong>إذا كان الذكاء الاصطناعي الذي تستخدمه لا يدعم إدخال الصور</strong>، فلن يتم التعرف على لقطات الشاشة، فيرجى استخدام طريقة النسخ واللصق للتواصل.</p></div><h2 id="تقنيات-المطالبات-التي-تجعل-الذكاء-الاصطناعي-يشرح-بشكل-جيد" tabindex="-1">تقنيات المطالبات التي تجعل الذكاء الاصطناعي &quot;يشرح بشكل جيد&quot; <a class="header-anchor" href="#تقنيات-المطالبات-التي-تجعل-الذكاء-الاصطناعي-يشرح-بشكل-جيد" aria-label="Permalink to “تقنيات المطالبات التي تجعل الذكاء الاصطناعي &quot;يشرح بشكل جيد&quot;”">​</a></h2><p>إذا كنت لا تريد الإجابة فقط، بل تريد &quot;تعلم&quot; الإجابة. استخدام تعليمات مشابهة لما يلي يمكن أن يحسن بشكل كبير من جودة الشرح:</p><blockquote><p><strong>مثال على سؤال تعليمي</strong></p><ul><li>&quot;يرجى شرح هذا المفهوم في 5 جمل أولاً، ثم أعطني بعض الأسئلة لاختبار ما إذا كنت قد فهمت بشكل صحيح.&quot;</li><li>&quot;يرجى شرح رسالة الخطأ هذه بالتفصيل، لا أفهم سبب الخطأ.&quot;</li></ul></blockquote><h1 id="بعد-المثابرة-لفترة-طويلة-ما-زلت-لا-أستطيع-الحل،-أريد-الاستسلام" tabindex="-1">بعد المثابرة لفترة طويلة ما زلت لا أستطيع الحل، أريد الاستسلام <a class="header-anchor" href="#بعد-المثابرة-لفترة-طويلة-ما-زلت-لا-أستطيع-الحل،-أريد-الاستسلام" aria-label="Permalink to “بعد المثابرة لفترة طويلة ما زلت لا أستطيع الحل، أريد الاستسلام”">​</a></h1><p>ربما تكون طريقة مثابرتك خاطئة. لا تعاني بمفردك في الظلام، يمكنك التحدث مع المؤلف والمساعدين التعليميين: أخبرهم بصدق عن الطرق التي جربتها، والنقاط المحددة التي واجهتها، وحالتك النفسية الحالية. في كثير من الأحيان، بمجرد تعديل الاتجاه قليلاً، أو إضافة نقطة معرفية رئيسية، يمكنك الاستمرار في المضي قدمًا.</p><h1 id="أعتقد-أن-بعض-تصميمات-الدورة-التعليمية-غير-معقولة" tabindex="-1">أعتقد أن بعض تصميمات الدورة التعليمية غير معقولة <a class="header-anchor" href="#أعتقد-أن-بعض-تصميمات-الدورة-التعليمية-غير-معقولة" aria-label="Permalink to “أعتقد أن بعض تصميمات الدورة التعليمية غير معقولة”">​</a></h1><p>نرحب بك دائمًا للتواصل مع المؤلف، أو تقديم مشكلة، أو تقديم ملاحظات مباشرة في المجموعة/الفصل. نأمل بشدة أن نعمل معك لتحسين هذه الدورة التعليمية: ما هو غير واضح، ما هي التجربة السيئة، ما الذي جعلك تهدر الجهد، يمكن الإشارة إليه بصراحة. كلما كانت الملاحظات أكثر واقعية وتحديدًا، زادت مساعدتها للقادمين الجدد لتجنب الأخطاء.</p><h1 id="المراجع" tabindex="-1">المراجع <a class="header-anchor" href="#المراجع" aria-label="Permalink to “المراجع”">​</a></h1><ul><li><a href="https://nju-projectn.github.io/ics-pa-gitbook/ics2025/" target="_blank" rel="noreferrer">جامعة نانجينغ قسم علوم الكمبيوتر والتكنولوجيا تجربة أساسيات أنظمة الكمبيوتر</a></li></ul>',50)),n(s,{title:"ماذا تتعلم بعد ذلك",description:"وفقًا لمسار 'من يعرف استخدام الذكاء الاصطناعي إلى يعرف صنع المنتجات'، استمر في المضي قدمًا.",items:d(a)},null,8,["items"])])}}});export{b as __pageData,q as default};
